// =============================================================================
// tflex_traffic_src -- descriptor-driven packet source (Milestone 1 stand-in
// for the accelerator model's packet builder).
//
// Accepts one pkt_hdr_t descriptor at a time and emits its packet as an item
// stream: the header (with inject_ts stamped from a free-running cycle
// counter), then ceil(payload_len / 28) payload words generated by
// tflex_pkg::payload_word(addr, tag, idx). Bytes past the length are zero.
// The next descriptor is accepted in the same cycle the last item leaves, so
// back-to-back packets have no bubble.
// =============================================================================
module tflex_traffic_src
  import tflex_pkg::*;
(
  input  logic       clk,
  input  logic       rst_n,
  input  logic       desc_valid,
  output logic       desc_ready,
  input  pkt_hdr_t   desc,
  output logic       out_valid,
  input  logic       out_ready,
  output pkt_item_t  out_item,
  output logic [63:0] cycle          // free-running cycle counter (inject_ts)
);
  typedef enum logic [1:0] {S_IDLE, S_HDR, S_PAY} state_e;

  state_e      state_q;
  pkt_hdr_t    hdr_q;
  logic [16:0] rem_q;        // payload bytes not yet emitted
  logic [15:0] idx_q;        // payload word index
  logic        last_item;
  logic        out_fire;
  logic [5:0]  nbytes;

  assign out_fire  = out_valid && out_ready;
  assign out_valid = (state_q != S_IDLE);
  assign last_item = (state_q == S_HDR) ? (payload_len(hdr_q) == 16'd0)
                                        : (rem_q <= 17'(BODY_BYTES));
  assign desc_ready = (state_q == S_IDLE) || (out_fire && last_item);
  assign nbytes     = (rem_q >= 17'(BODY_BYTES)) ? 6'(BODY_BYTES) : rem_q[5:0];

  always_comb begin
    if (state_q == S_HDR)
      out_item = '{sop: 1'b1, eop: last_item, data: hdr_q};
    else
      out_item = '{sop: 1'b0, eop: last_item,
                   data: keep_bytes(payload_word(hdr_q.addr, hdr_q.tag, idx_q), nbytes)};
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state_q <= S_IDLE;
      hdr_q   <= '0;
      rem_q   <= '0;
      idx_q   <= '0;
      cycle   <= '0;
    end else begin
      cycle <= cycle + 64'd1;
      if (desc_valid && desc_ready) begin
        pkt_hdr_t h;
        h           = desc;
        h.inject_ts = cycle;
        hdr_q   <= h;
        state_q <= S_HDR;
      end else if (out_fire) begin
        if (state_q == S_HDR) begin
          state_q <= last_item ? S_IDLE : S_PAY;
          rem_q   <= 17'(payload_len(hdr_q));
          idx_q   <= '0;
        end else begin
          if (last_item) state_q <= S_IDLE;
          rem_q <= rem_q - 17'(BODY_BYTES);
          idx_q <= idx_q + 16'd1;
        end
      end
    end
  end
endmodule
